import {
    Table,
    ChoiceColumn,
    StringColumn,
    GuidColumn,
    TranslatedFieldColumn,
    BooleanColumn,
    DomainIdColumn,
    DomainPathColumn,
    ReferenceColumn,
} from '@servicenow/sdk/core'

export const business_calendar = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'label',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Business Calendar',
    name: 'business_calendar',
    schema: {
        cal_type: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            label: 'Calendar Type',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 1000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        label: TranslatedFieldColumn({
            label: 'Label',
            mandatory: true,
            maxLength: 80,
        }),
        is_legacy_schedule: BooleanColumn({
            default: false,
            label: 'Is legacy schedule',
        }),
        time_zone: StringColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_user',
                field: 'time_zone',
            },
            label: 'Time zone',
        }),
        calendar_name: StringColumn({
            label: 'Name',
            mandatory: true,
            maxLength: 80,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the schedule belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        parent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Parent calendar which constrains the times for which this schedule is valid',
                    label: 'Parent',
                    plural: 'Parents',
                    language: 'en',
                },
            ],
            referenceTable: 'business_calendar',
            referenceQual: 'is_legacy_schedule=false',
        }),
        plural_label: TranslatedFieldColumn({
            label: 'Plural label',
            mandatory: true,
            maxLength: 80,
        }),
    },
})
